pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        vm.prank(address(this));
        c.burn(0);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(!ok);
    }
}
